import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry depthwise_conv2d_kx1(
    .param .u64 in_ptr,
    .param .u64 wt_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .s32 total,
    .param .s32 channels,
    .param .s32 height,
    .param .s32 width,
    .param .s32 out_h,
    .param .s32 out_w,
    .param .s32 ksize,
    .param .s32 stride,
    .param .s32 pad,
    .param .s32 dil,
    .param .s32 has_bias
)
{
    .reg .pred %p<12>;
    .reg .b32 %r<48>;
    .reg .b64 %rd<24>;
    .reg .f32 %f<16>;

    mov.u32 %r1, %tid.x;
    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ntid.x;
    mad.lo.u32 %r4, %r2, %r3, %r1;              // tid

    ld.param.s32 %r5, [total];
    setp.ge.s32 %p1, %r4, %r5;
    @%p1 bra DONE;

    ld.param.s32 %r6, [out_w];
    ld.param.s32 %r7, [out_h];
    ld.param.s32 %r8, [channels];

    div.s32 %r9, %r4, %r6;                     // tmp = tid / OW
    rem.s32 %r10, %r4, %r6;                    // ow
    div.s32 %r11, %r9, %r7;                    // nc = n*C+c
    rem.s32 %r12, %r9, %r7;                    // oh
    div.s32 %r13, %r11, %r8;                   // n
    rem.s32 %r14, %r11, %r8;                   // c

    ld.param.s32 %r15, [stride];
    ld.param.s32 %r16, [pad];
    ld.param.s32 %r17, [width];
    ld.param.s32 %r18, [height];
    ld.param.s32 %r19, [ksize];
    ld.param.s32 %r20, [dil];

    mul.lo.s32 %r21, %r10, %r15;
    sub.s32 %r21, %r21, %r16;                  // iw
    mul.lo.s32 %r22, %r12, %r15;
    sub.s32 %r22, %r22, %r16;                  // ih0

    mov.f32 %f1, 0f00000000;                   // acc

    setp.lt.s32 %p2, %r21, 0;
    setp.ge.s32 %p3, %r21, %r17;
    or.pred %p4, %p2, %p3;
    @%p4 bra BIAS;

    mov.s32 %r23, 0;                           // kh
K_LOOP:
    setp.ge.s32 %p5, %r23, %r19;
    @%p5 bra BIAS;

    mad.lo.s32 %r24, %r23, %r20, %r22;         // ih
    setp.lt.s32 %p6, %r24, 0;
    setp.ge.s32 %p7, %r24, %r18;
    or.pred %p8, %p6, %p7;
    @%p8 bra NEXT_K;

    mad.lo.s32 %r25, %r14, %r19, %r23;         // c*K + kh
    cvt.u64.s32 %rd1, %r25;
    shl.b64 %rd2, %rd1, 2;
    ld.param.u64 %rd3, [wt_ptr];
    add.s64 %rd4, %rd3, %rd2;
    ld.global.f32 %f2, [%rd4];

    cvt.u64.s32 %rd5, %r11;                    // nc
    cvt.u64.s32 %rd6, %r18;
    mul.lo.u64 %rd7, %rd5, %rd6;
    cvt.u64.s32 %rd8, %r24;
    add.s64 %rd7, %rd7, %rd8;
    cvt.u64.s32 %rd9, %r17;
    mul.lo.u64 %rd7, %rd7, %rd9;
    cvt.u64.s32 %rd10, %r21;
    add.s64 %rd7, %rd7, %rd10;
    shl.b64 %rd7, %rd7, 2;
    ld.param.u64 %rd11, [in_ptr];
    add.s64 %rd12, %rd11, %rd7;
    ld.global.f32 %f3, [%rd12];

    fma.rn.f32 %f1, %f3, %f2, %f1;

NEXT_K:
    add.s32 %r23, %r23, 1;
    bra K_LOOP;

BIAS:
    ld.param.s32 %r26, [has_bias];
    setp.eq.s32 %p9, %r26, 0;
    @%p9 bra STORE;
    cvt.u64.s32 %rd13, %r14;
    shl.b64 %rd14, %rd13, 2;
    ld.param.u64 %rd15, [bias_ptr];
    add.s64 %rd16, %rd15, %rd14;
    ld.global.f32 %f4, [%rd16];
    add.f32 %f1, %f1, %f4;

STORE:
    cvt.u64.s32 %rd17, %r4;
    shl.b64 %rd18, %rd17, 2;
    ld.param.u64 %rd19, [out_ptr];
    add.s64 %rd20, %rd19, %rd18;
    st.global.f32 [%rd20], %f1;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("depthwise_conv2d_kx1")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super().__init__()
        self.conv2d = nn.Conv2d(in_channels, in_channels, kernel_size=(kernel_size, 1), stride=stride, padding=padding, dilation=dilation, groups=in_channels, bias=bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        n, c, h, w = x.shape
        k = int(self.conv2d.kernel_size[0])
        s = int(self.conv2d.stride[0])
        p = int(self.conv2d.padding[0])
        d = int(self.conv2d.dilation[0])

        oh = (h + 2 * p - d * (k - 1) - 1) // s + 1
        ow = (w + 2 * p - 1) // s + 1
        out = torch.empty((n, c, oh, ow), device=x.device, dtype=x.dtype)

        total = n * c * oh * ow
        if total != 0:
            module = _get_ptx_module()
            bias_tensor = self.conv2d.bias if self.conv2d.bias is not None else out
            has_bias = 1 if self.conv2d.bias is not None else 0
            module.launch(
                "depthwise_conv2d_kx1",
                grid=((total + 255) // 256, 1, 1),
                block=(256, 1, 1),
                arguments=[
                    x,
                    self.conv2d.weight,
                    bias_tensor,
                    out,
                    i32(total),
                    i32(c),
                    i32(h),
                    i32(w),
                    i32(oh),
                    i32(ow),
                    i32(k),
                    i32(s),
                    i32(p),
                    i32(d),
                    i32(has_bias),
                ],
                shared_memory=0,
                stream=torch.cuda.current_stream(x.device),
            )
        return out

